package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_distance_TriageGen1Test {

    private static final double DELTA = 1e-9;

    @Test
    public void testDistance_ZeroDistance() {
        int[] p1 = {0, 0, 0};
        int[] p2 = {0, 0, 0};
        double expected = 0.0;
        double actual = MathUtils.distance(p1, p2);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testDistance_IdenticalPoints() {
        int[] p1 = {1, 2, 3};
        int[] p2 = {1, 2, 3};
        double expected = 0.0;
        double actual = MathUtils.distance(p1, p2);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testDistance_TwoDimensional() {
        int[] p1 = {0, 0};
        int[] p2 = {3, 4};
        // sqrt((3-0)^2 + (4-0)^2) = sqrt(9 + 16) = 5
        double expected = 5.0;
        double actual = MathUtils.distance(p1, p2);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testDistance_ThreeDimensional() {
        int[] p1 = {1, 2, 3};
        int[] p2 = {4, 5, 6};
        // sqrt((4-1)^2 + (5-2)^2 + (6-3)^2) = sqrt(9 + 9 + 9) = sqrt(27)
        double expected = Math.sqrt(27.0);
        double actual = MathUtils.distance(p1, p2);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testDistance_NegativeCoordinates() {
        int[] p1 = {-1, -1};
        int[] p2 = {-4, -5};
        // sqrt((-4 - -1)^2 + (-5 - -1)^2) = sqrt((-3)^2 + (-4)^2) = 5
        double expected = 5.0;
        double actual = MathUtils.distance(p1, p2);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testDistance_SingleElement() {
        int[] p1 = {10};
        int[] p2 = {20};
        // sqrt((20-10)^2) = 10
        double expected = 10.0;
        double actual = MathUtils.distance(p1, p2);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testDistance_EmptyArrays() {
        int[] p1 = {};
        int[] p2 = {};
        // sum = 0, sqrt(0) = 0
        double expected = 0.0;
        double actual = MathUtils.distance(p1, p2);
        assertEquals(expected, actual, DELTA);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testDistance_MismatchedLengths_P1Larger() {
        int[] p1 = {1, 2, 3};
        int[] p2 = {1, 2};
        MathUtils.distance(p1, p2);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testDistance_MismatchedLengths_P2Larger() {
        int[] p1 = {1, 2};
        int[] p2 = {1, 2, 3};
        MathUtils.distance(p1, p2);
    }
}
